//! Ident, the Object attribute every AST Object has, written and read as
//! C writes and reads it: in the Object part of a description whenever it
//! is set, even blank, and read only from that part. A KeyMap holds one
//! too, as does each KeyMap nested in it.
//!
//! `ident_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/ident_probe.c`.

use crate::common::native_dump;
#[path = "ident_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrameBuilder, Frame, FrameRef, FrameSet};
use starlink_ast::mappings::{Mapping, UnitMap, ZoomMap};
use starlink_ast::{AnyObject, KeyMap, from_native_string};

fn text(lines: &[&str]) -> String {
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

fn assert_dump(name: &str, obj: &AnyObject, want: &[&str]) {
    assert_eq!(native_dump(obj).unwrap(), text(want), "{name}");
}

#[test]
fn keymap_idents_are_written_as_c_writes_them() {
    let mut inner = KeyMap::new();
    inner.set_ident("inner map");
    inner.put_0i("x", 7, None).unwrap();
    let mut km = KeyMap::new();
    km.set_ident("outer map");
    km.put_0a("inner", AnyObject::KeyMap(Box::new(inner)), None)
        .unwrap();
    assert_dump(
        "idents",
        &AnyObject::KeyMap(Box::new(km)),
        cases::DUMP_IDENTS,
    );

    let mut km = KeyMap::new();
    km.put_0i("a", 1, None).unwrap();
    assert!(!km.test_ident());
    assert_dump(
        "no ident",
        &AnyObject::KeyMap(Box::new(km)),
        cases::DUMP_NO_IDENT,
    );
}

/// A blank Ident is set, and is written, for every family of Object.
#[test]
fn a_blank_ident_is_set_and_written() {
    let mut km = KeyMap::new();
    km.set_ident("");
    assert!(km.test_ident());
    assert_dump(
        "keymap",
        &AnyObject::KeyMap(Box::new(km)),
        cases::DUMP_BLANK_KEYMAP,
    );

    let mut zoom = ZoomMap::new(1, 2.0).unwrap();
    zoom.set_ident("");
    assert!(zoom.test_ident());
    assert_dump(
        "zoommap",
        &AnyObject::ZoomMap(zoom),
        cases::DUMP_BLANK_ZOOMMAP,
    );

    let mut frame = BasicFrameBuilder::new(1).build().unwrap();
    Frame::set_ident(&mut frame, "").unwrap();
    assert!(Frame::test_ident(&frame));
    assert_dump(
        "frame",
        &AnyObject::BasicFrame(frame),
        cases::DUMP_BLANK_FRAME,
    );

    let one = || Box::new(BasicFrameBuilder::new(1).build().unwrap());
    let mut fs = FrameSet::new(one());
    fs.add_frame(FrameRef::Base, Box::new(UnitMap::new(1)), one())
        .unwrap();
    Frame::set_ident(&mut fs, "").unwrap();
    assert!(Frame::test_ident(&fs));
    assert_dump(
        "frameset",
        &AnyObject::FrameSet(fs),
        cases::DUMP_BLANK_FRAMESET,
    );
}

/// Each blank dump reads back with its blank Ident set.
#[test]
fn a_blank_ident_reads_back_set() {
    for dump in [
        cases::DUMP_BLANK_KEYMAP,
        cases::DUMP_BLANK_ZOOMMAP,
        cases::DUMP_BLANK_FRAME,
        cases::DUMP_BLANK_FRAMESET,
    ] {
        let obj = from_native_string(&text(dump)).unwrap();
        let (ident, set) = match &obj {
            AnyObject::KeyMap(km) => (km.ident().to_string(), km.test_ident()),
            other => match other.as_frame() {
                Some(f) => (f.ident().to_string(), f.test_ident()),
                None => {
                    let m = other.as_mapping().expect("a Mapping");
                    (m.ident().to_string(), m.test_ident())
                }
            },
        };
        assert_eq!((ident.as_str(), set), ("", true), "{}", dump[0]);
    }
}

#[test]
fn keymap_idents_are_read_as_c_reads_them() {
    let mut failures = Vec::new();
    for &(name, lines, want, want_inner) in cases::READS {
        let AnyObject::KeyMap(km) = from_native_string(&text(lines)).unwrap() else {
            panic!("{name}: not a KeyMap");
        };
        let got = (km.ident(), km.test_ident());
        let got_inner = match km.get_0a("inner").unwrap() {
            Some(Some(AnyObject::KeyMap(inner))) => {
                Some((inner.ident().to_string(), inner.test_ident()))
            }
            _ => None,
        };
        let want_inner = want_inner.map(|(s, t)| (s.to_string(), t));
        if got != want || got_inner != want_inner {
            failures.push(format!(
                "{name}: got {:?}, C gives {:?}",
                (got, &got_inner),
                (want, &want_inner)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
